static inline __attribute__((unused)) lb_o_u8_span lb_alloc_call(lb_iface a, size_t size, size_t alignment) { if (a.vtable == NULL) lb_trap("memory.unset"); return ((const lb_vt_Allocator*)a.vtable)->allocate(a.data, size, alignment); }
static inline bool __attribute__((unused)) lb_resize_call(lb_iface a, lb_span block, size_t size) { if (a.vtable == NULL) lb_trap("memory.unset"); return ((const lb_vt_Allocator*)a.vtable)->resize(a.data, block, size); }
static inline void __attribute__((unused)) lb_release_call(lb_iface a, lb_span block) { if (a.vtable == NULL) return; ((const lb_vt_Allocator*)a.vtable)->release(a.data, block); }
